/**
 * The star table the astronomy corner ships, and the 88 IAU constellations by
 * name. Data only: `stars.ts` reads it and does the geometry.
 *
 * **Sources, all fetched 2026-10-10 and cited rather than paraphrased** (the
 * R11 research of 2026-10-09 chose them and read their licences; the files it
 * left in `../research/sky/samples` are byte-identical to what this run
 * re-fetched):
 *
 *  - Positions, V magnitudes and B-V colour indices: Yale Bright Star
 *    Catalogue, 5th revised edition (Hoffleit & Warren 1991), CDS/VizieR
 *    catalogue V/50, queried through the ASU service:
 *    `https://cdsarc.cds.unistra.fr/viz-bin/asu-tsv?-source=V/50`. The subset is
 *    `Vmag <= 6.0`: 5080 stars. 53 of them carry no B-V in the catalogue,
 *    kept here as `NaN` rather than guessed, because a colour index is a
 *    measurement.
 *  - Proper names: IAU Working Group on Star Names, "IAU Catalog of Star Names"
 *    (last updated 2022-04-04), joined to the catalogue by HR number: 310
 *    stars of the subset have one.
 *  - Latin names and abbreviations: the IAU's own constellation table,
 *    `https://www.iau.org/IAU/IAU/Astronomy-FAQs/Constellations.aspx`.
 *  - English names: the same table's "English Name" column, kept as the IAU
 *    writes it ("The Princess", "Air Pump"). The leading article is the
 *    source's, not an edit.
 *  - Serbian names: the Serbian Wikipedia list "Spisak sazvezda", read in its
 *    own Latin-script (sr-el) rendering so the names arrive with the Serbian
 *    letters (s, c with the carons) this app writes rather than transliterated
 *    here: `https://sr.wikipedia.org/sr-el/Spisak_sazvezdja`. One cell (Antlia)
 *    the sr-el rendering left in Cyrillic is transliterated mechanically with
 *    the standard Serbian Cyrillic-to-Latin table, and that is the only one.
 *    Names are CITED, never translated by this project.
 *
 * **What this table deliberately does NOT contain: stick figures.** The IAU
 * defines no figures ("For IAU constellations, no stick figures or figurative
 * painting styles are formally defined"), so every figure set is somebody's
 * creative work under its own licence - and the sets the research cleared
 * (Stellarium's and Barbier's edge lists, and d3-celestial's lines) are
 * CC BY-SA 4.0, whose share-alike term cannot be applied to a file inside this
 * Apache-2.0 tree without the maintainer's legal review. `Constellation.lines`
 * is therefore empty for all 88 and the star map draws names, not figures.
 *
 * **Where a constellation's name is drawn.** `CONSTELLATION_ANCHORS` below holds
 * one anchor per constellation: the mean direction of the IAU's own boundary
 * vertices for that region (the per-constellation boundary files on the IAU's
 * constellation pages), taken as unit vectors so a region straddling right
 * ascension 0 does not average to the wrong side of the sky. The boundary files
 * themselves are not shipped - they are not this part's data, and an anchor is
 * the only thing a name needs.
 *
 * **The licence position, stated rather than implied.** The IAU and IAU WGSN
 * material is IAU-produced content, released under Creative Commons
 * Attribution; the Serbian names come from Wikipedia under CC BY-SA 4.0. Both
 * ask for credit, which this header gives. Whether a data pack carrying BY-SA
 * content may ship inside an Apache-2.0 repository is one of the R11 report's
 * open questions for the maintainer, and no licence text is invented here to
 * close it.
 */
