/** One constellation's three names and its IAU abbreviation. */
export interface ConstellationNames {
  /** The IAU three-letter abbreviation, which is also the contract's `Constellation.id`. */
  readonly id: string;
  readonly latin: string;
  readonly sr: string;
  readonly en: string;
}

